using LoyaltyService.Application;
namespace LoyaltyService.Api; public static class Endpoints { public static void MapLoyaltyEndpoints(this WebApplication app) { app.MapGet("/manage/health", () => Results.Ok(new { status = "UP" })); app.MapGet("/internal/loyalty/{username}", async (string username, HttpContext context, LoyaltyApplication s, CancellationToken ct) => Results.Ok(await s.GetAsync(context.User.Identity!.Name!, ct))); app.MapPost("/internal/loyalty/{username}/reservations", async (string username, HttpContext context, LoyaltyApplication s, CancellationToken ct) => Results.Ok(await s.IncrementAsync(context.User.Identity!.Name!, ct))); app.MapDelete("/internal/loyalty/{username}/reservations", async (string username, HttpContext context, LoyaltyApplication s, CancellationToken ct) => Results.Ok(await s.DecrementAsync(context.User.Identity!.Name!, ct))); } }
